"""Bind closed final-v2 exact pilots to new primary fixture definitions, without Java."""
from collections import Counter
from datetime import datetime, timezone
import importlib.util
import json
from pathlib import Path
import sys

PHASE = Path(__file__).resolve().parent.parent
BENCH = PHASE / 'benchmark'
ROOT = PHASE.parents[1]
sys.path.insert(0, str(BENCH))
import run_comparison as runner
import analyze_comparison as analysis

spec = importlib.util.spec_from_file_location('independent_admission_audit', Path(__file__).with_name('audit_admission_cohort.py'))
independent = importlib.util.module_from_spec(spec)
spec.loader.exec_module(independent)
need, read, sha = runner.require, runner.read, runner.sha


def evidence(path):
    return {'path': str(path.relative_to(ROOT)), 'sha256': sha(path)}


def class_hashes(root):
    return {p.relative_to(root).as_posix(): sha(p) for p in sorted(root.rglob('*.class'))}


def main():
    definitions_path = BENCH / 'fixture-definitions-v1.json'
    qualification_path = BENCH / 'qualification/final-runtime-v1.json'
    need(not definitions_path.exists() and not qualification_path.exists(), 'Preserve existing qualification outputs')
    expected_scripts = {'run_comparison.py': 'f4ba46abe49f9f87fa0ae5e140c601c62880dcb1e11b2a14933d04f3c8b55be6',
                        'analyze_comparison.py': 'beb742cf96ca3144abf955aebd2109e2eff4a58b05f163a8e85c91155c0d6c16'}
    need(all(sha(BENCH / name) == value for name, value in expected_scripts.items()), 'Reviewed scripts changed')
    oracle_path = BENCH / 'fixture-oracles-v1.json'
    oracles = read(oracle_path)
    need(sha(BENCH / 'fixture_oracle.py') == oracles['oracleSourceSha256'], 'Independent oracle source changed')
    cp_file = BENCH / 'runtime-v2/classpath.txt'
    classpath, runtime_inputs = runner.classpath_inputs(cp_file)
    need(classpath[:2] == [str(BENCH / 'runtime-v2/classes'), str(PHASE / 'runtime-v2/classes')],
         'Final harness/memo overlay order changed')
    jdk_inputs = runner.jdk_inputs(runner.JAVA)
    memo_qualification_path = PHASE / 'runtime-v2/ownership-qualification.json'
    memo_qualification = read(memo_qualification_path)
    manifests = [PHASE / f'runtime-v{version}/class-files.json' for version in (1, 2)]
    need(read(manifests[0]) == read(manifests[1]) and len(read(manifests[1])) == 7,
         'Formatted memo runtime differs from tested bytecode')
    for version, manifest in zip((1, 2), manifests):
        need(sha(manifest) == memo_qualification[f'runtimeV{version}ClassManifest']
             and class_hashes(PHASE / f'runtime-v{version}/classes') == read(manifest), 'Memo class manifest failed')
    group_evidence, executions = [], 0
    for group, expected in memo_qualification['groups'].items():
        path = PHASE / 'contracts/validation' / group / 'receipt.json'
        receipt = read(path)
        need(sha(path) == expected['receiptSha256'] and receipt['results'] == expected['results']
             and receipt['passed'] is True and receipt['testProcessExit'] == 0
             and all(receipt['results'][k] == 0 for k in ('errors', 'failures', 'skipped')), 'Ownership test receipt failed')
        executions += receipt['results']['tests']
        group_evidence.append({**evidence(path), 'results': receipt['results']})
    need(executions == memo_qualification['qualifiedExecutions'] == 225, 'Wrong ownership execution count')
    baseline_path = PHASE / 'recovery/root-baseline-class-comparison.json'
    baseline_receipt = read(baseline_path)
    baseline = class_hashes(ROOT / 'result-coordinate-evidence/retention-followup/recovery/runtime-v1/baseline/artifacts/001-classes')
    current = class_hashes(ROOT / 'core/sail/lmdb/target/classes')
    need(baseline_receipt == {'classCounts': [2778, 2778], 'changed': [], 'missing': [], 'added': []}
         and len(baseline) == len(current) == 2778 and baseline == current, 'Current root and preserved base classes differ')
    harness_receipt_path = BENCH / 'runtime-v2/compile-receipt.json'
    harness_receipt = read(harness_receipt_path)
    harness_manifest = BENCH / 'runtime-v2/class-files.json'
    need(harness_receipt['compiled'] is True and harness_receipt['classpathSha256'] == sha(cp_file)
         and harness_receipt['classFilesSha256'] == sha(harness_manifest)
         and class_hashes(BENCH / 'runtime-v2/classes') == read(harness_manifest)
         and all(sha(path) == value for path, value in harness_receipt['sourceHashes'].items()),
         'Final harness compilation identity failed')
    definitions, pilots = [], []
    first_inputs = None
    process_intervals = []
    for prefix, expected_fixture in zip(('early', 'late', 'unique'), oracles['fixtures']):
        args, expected = expected_fixture['arguments'], expected_fixture['expected']
        independent_oracle = independent.fixture_oracle(args)
        need(independent_oracle['rows'] == expected['expectedRows']
             and independent_oracle['checksum'] == expected['expectedChecksum']
             and all(independent_oracle[k] == expected[k] for k in ('querySha256', 'insertionRecipeSha256',
                                                                   'projectedLexicalChars')), 'Independent ASCII oracle failed')
        matched_metadata, matched_route, projection = None, None, None
        hits_minimum = None
        for arm in runner.ARMS:
            folder = BENCH / 'qualification' / f'{prefix}-{arm}-v2'
            process, launch = read(folder / 'process.json'), read(folder / 'command.json')
            need(process['exitCode'] == 0 and process['timedOut'] is False and process['inputsUnchanged'] is True
                 and process['comparisonSample'] is False
                 and process['startedEpochNs'] == launch['startedEpochNs'] <= process['finishedEpochNs'],
                 'Final exact pilot did not finish cleanly')
            need(all(sha(folder / name) == value for name, value in process['rawHashes'].items()), 'Pilot raw seal failed')
            process_intervals.append((process['startedEpochNs'], process['finishedEpochNs']))
            command = launch['argv']
            cp_at = command.index('-cp')
            need(command[0] == str(runner.JAVA) and command[cp_at + 1] == ':'.join(classpath)
                 and command[cp_at + 2] == runner.MAIN and launch['cwd'] == str(ROOT), 'Pilot runtime/classpath differs')
            properties = {runner.TRANSPORT: 'off', runner.ENABLED: str(arm != 'ordinary').lower(),
                          runner.RETENTION: 'weak', runner.ADMISSION: 'always' if arm == 'always' else 'initial'}
            need(Counter(command[1:cp_at]) == Counter(runner.JVM +
                 ['-Xlog:gc:file=' + str(folder / 'gc.log') + ':uptime,level,tags'] +
                 ['-D' + key + '=' + value for key, value in properties.items()]), 'Pilot JVM settings differ')
            cli = command[cp_at + 3:]
            parsed = dict(arg[2:].split('=', 1) for arg in cli)
            wanted = {key: str(value) for key, value in args.items()}
            wanted.update(arm=arm, source='admission-exact-pilot-v1', warmup='2', iterations='1', trace='false',
                          **{'exact-oracle': 'true', 'output': str(folder / 'samples.jsonl'), 'store': str(folder / 'store')})
            need(parsed == wanted and len(parsed) == len(cli), 'Pilot query dimensions or consumer differ')
            inputs = read(folder / 'inputs.json')
            first_inputs = inputs if first_inputs is None else first_inputs
            need(inputs == first_inputs, 'Pilot input identity differs across final-v2 arms or fixtures')
            records = analysis.json_lines(folder / 'samples.jsonl')
            need(len(records) == 5 and records[0]['type'] == 'metadata' and records[-1]['type'] == 'completion',
                 'Expected all three exact pilot queries')
            metadata, samples, completion = records[0], records[1:-1], records[-1]
            analysis.subset(metadata, {**expected, **runner.CONFIG, 'arm': arm, 'source': parsed['source'],
                'store': str(folder / 'store'), 'admission': properties[runner.ADMISSION], 'trace': False,
                'exactOracle': True, 'oracleMode': 'exact-ordered-lexical', 'timingEligible': False,
                'timingAccepted': False, 'warmup': 2, 'measurementsToRun': 1, 'memoStatisticsCapacity': 3,
                'sourceCacheSettingsChanged': False, 'retainedOrderedRows': True, 'reopenedAfterPopulation': True,
                'maxHeapBytes': 1073741824, 'javaVersion': '25.0.5+8-LTS'}, 'Exact pilot metadata')
            need(metadata['jvmArguments'] == command[1:cp_at]
                 and metadata['systemProperties'] == {'rdf4j.lmdb.hotCounters': 'true',
                     'rdf4j.lmdb.queryMemory.perQueryMaxBytes': '536870912', **properties}, 'Observed pilot flags changed')
            normalized = analysis.normalized_metadata(metadata)
            matched_metadata = normalized if matched_metadata is None else matched_metadata
            need(matched_metadata == normalized, 'Cross-arm exact fixture metadata differs')
            observations = []
            for index, sample in enumerate(samples):
                analysis.subset(sample, {'type': 'sample', 'arm': arm, 'iteration': index - 2,
                    'stage': 'warmup' if index < 2 else 'measurement', 'admission': properties[runner.ADMISSION],
                    'consumption': 'full', 'rows': expected['expectedRows'], 'checksum': expected['expectedChecksum'],
                    'expectedChecksum': expected['expectedChecksum'], 'expectedFullChecksum': expected['expectedChecksum'],
                    'projectedOpportunities': expected['projectedOpportunities'], 'nativeProjectedRows': expected['expectedRows'],
                    'retainedRows': 0, 'ledgerBeforeBytes': 0, 'ledgerAfterBytes': 0, 'queryLedgerPeakBytes': None,
                    'memoOverflowCount': 0, 'omittedSelections': 0, 'exactOracle': True,
                    'oracleMode': 'exact-ordered-lexical', 'orderedExactLexicalOracleValid': True,
                    'timingEligible': False, 'timingAccepted': False,
                    **{key: True for key in ('valid', 'complete', 'rowCountValid', 'checksumValid', 'ledgerReleased',
                        'memoLifecycleValid', 'autoRequested', 'auto', 'nativeRouteObserved')}}, 'Exact query result/lifetime')
                analysis.subset(sample['counters'], {**analysis.ORDERED_COUNTERS, 'hostedGeneric': 0,
                    'unhostedHardDeclines': 0, 'leftJoinReplayMaterializations': 0}, 'Actual ordered native execution')
                need(sample['successfulSelections'] == analysis.ORDERED_SELECTIONS, 'Expected normal ordered-factorized AUTO')
                route = analysis.route(sample)
                matched_route = route if matched_route is None else matched_route
                need(route == matched_route, 'Route/adjacency changed across exact queries')
                current_projection = {key: sample[key] for key in ('nativeProjectedRows', 'projectedBindingSetsCreated')}
                projection = current_projection if projection is None else projection
                need(current_projection == projection, 'Projection construction changed')
                adjacency, setup = sample['adjacency'], metadata['adjacencySetup']
                need(setup['state'] == adjacency['stateBefore'] == adjacency['stateAfter'] == 'ACTIVE'
                     and setup['currentRevisionReady'] is True
                     and len({setup['appliedRevision'], setup['currentDataRevision'], adjacency['appliedRevisionBefore'],
                              adjacency['currentRevisionBefore'], adjacency['appliedRevisionAfter'],
                              adjacency['currentRevisionAfter']}) == 1, 'Adjacency is not active/current')
                hits_minimum = adjacency['lookupHits'] if hits_minimum is None else min(hits_minimum, adjacency['lookupHits'])
                owner_count = int(arm != 'ordinary')
                need(sample['memoOpenedDelta'] == sample['memoClosedDelta'] == len(sample['memoOwners']) == owner_count,
                     'Wrong exact-pilot memo ownership')
                for owner in sample['memoOwners']:
                    independent.check_owner(owner, sample, index, arm)
                    analysis.inspect_owner({'metadataReservation': {'arrayBase': 80, 'arrayPerSlot': 36,
                        'weakMetadataPerSlot': 112, 'weakMetadataOverlap': 160}}, owner, sample, index, arm)
                hits = sum(owner['hits'] for owner in sample['memoOwners'])
                need(sample['projectedMaterializedValues'] + hits == sample['projectedOpportunities'],
                     'Qualified full exposure identity failed')
                need(sample['counters']['lazyValueCalls'] == sample['projectedMaterializedValues']
                     and sample['sourceLazyCallsAtPrefixBoundary'] == sample['projectedMaterializedValuesAtPrefixBoundary'],
                     'Exact pilot source/projection scope changed')
                observations.append({key: sample[key] for key in ('iteration', 'rows', 'projectedOpportunities',
                    'projectedMaterializedValues', 'sourceLazyCallsAtPrefixBoundary', 'ledgerPeakBytes', 'memoOwners')})
            analysis.subset(completion, {'harnessReturned': True, 'queries': 3, 'warmups': 2, 'measurements': 1,
                'semanticNativeCompilesTotal': 3, 'hostedGenericTotal': 0, 'unhostedHardDeclinesTotal': 0,
                'memoOpenedTotal': 3 * int(arm != 'ordinary'), 'memoClosedTotal': 3 * int(arm != 'ordinary'),
                'memoStatisticsSize': 3 * int(arm != 'ordinary'), 'memoOverflowCount': 0, 'ledgerAfterBytes': 0},
                'Closed pilot completion')
            independent.gc_observations(folder / 'gc.log')
            pilots.append({'fixture': expected_fixture['id'], 'arm': arm, 'queries': 3,
                           'comparisonSample': False, 'evidence': [evidence(folder / name) for name in
                               ('process.json', 'command.json', 'inputs.json', 'samples.jsonl', 'gc.log', 'pilot-validation.json')],
                           'observedCountersNotAdmissionGates': observations})
        definitions.append({'id': expected_fixture['id'], 'arguments': args,
            'oracle': {'rows': expected['expectedConsumedRows'], 'fullRows': expected['expectedRows'],
                       'checksum': expected['expectedConsumedChecksum'], 'fullChecksum': expected['expectedChecksum']},
            'metadata': expected,
            'qualification': {'measuredTier': 'ordered-factorized', 'minimumAdjacencyLookupHits': hits_minimum,
                'adjacencyExplanation': 'All nine exact queries for this fixture used the active, current native '
                    'star adjacency route and normal ORDER orderedFactorizedSort; no generic fallback or IR execution. '
                    'The hidden row ordering key did not create projected memo probes.',
                'sampleCounters': {key: matched_route['counters'][key] for key in analysis.ROUTE_COUNTERS},
                'projection': projection}})
    process_intervals.sort()
    need(all(left[1] <= right[0] for left, right in zip(process_intervals, process_intervals[1:])),
         'Final pilot JVMs overlapped')
    for raw_path, expected in first_inputs.items():
        path = Path(raw_path)
        if isinstance(expected, str):
            need(sha(path) == expected, 'Pilot fixed file changed: ' + str(path))
        else:
            actual = {p.relative_to(path).as_posix(): sha(p) for p in path.rglob('*') if p.is_file()}
            need(actual == expected, 'Pilot fixed directory changed: ' + str(path))
    definition_document = {'format': 1, 'fixtures': definitions}
    analysis.validate_definitions(definition_document)
    runner.write(definitions_path, definition_document)
    qualification = {'format': 'admission-final-runtime-qualification-v1', 'createdUtc': datetime.now(timezone.utc).isoformat(),
        'qualifiedForTiming': True, 'exactOracleQualified': True,
        'fixtureDefinitionsSha256': sha(definitions_path), 'classpathFileSha256': sha(cp_file),
        'runtimeInputsSha256': analysis.object_sha(runtime_inputs), 'javaSha256': sha(runner.JAVA),
        'jdkInputsSha256': analysis.object_sha(jdk_inputs), 'java': str(runner.JAVA), 'classpathFile': str(cp_file),
        'reviewedScripts': expected_scripts, 'builder': evidence(Path(__file__)),
        'independentOracle': evidence(oracle_path), 'independentAsciiOracle': evidence(Path(independent.__file__)),
        'ownership': {**evidence(memo_qualification_path), 'qualifiedExecutions': executions,
                      'identicalMemoClassFiles': 7, 'testGroups': group_evidence},
        'rootBaseline': {**evidence(baseline_path), 'identicalClassFiles': 2778,
                         'independentlyRehashedClassMapSha256': analysis.object_sha(current)},
        'harnessCompilation': evidence(harness_receipt_path), 'pilotJvms': 9, 'exactQueryExecutions': 27,
        'pilots': pilots, 'comparisonSamples': 0,
        'scope': 'Qualifies the final runtime, full fixture oracle, exposure, AUTO route, owner lifecycle and ledger '
                 'cleanup. Exact pilots use two warmups plus one query with statistics capacity three; primary timing '
                 'uses eight warmups plus five checksum-only queries with capacity thirteen. Every primary query '
                 'still passes frozen result/exposure/route/cleanup gates. No pilot latency or allocation estimate '
                 'was used to choose fixtures, tune the treatment, exclude a process, or enter the timing cohort.',
        'memoryScope': 'Process authority ledger endpoints and memo metadata/resize reservations; no separate '
                       'query-ledger peak or complete retained-heap estimate.',
        'retentionRestriction': 'Ordered wrappers may retain consumed Values. The timing cohort does not establish '
                                'useful-key weak collection or source decode counts.',
        'javaLaunchesByThisBuilder': 0}
    runner.write(qualification_path, qualification)
    print(json.dumps({'fixtureDefinitions': evidence(definitions_path), 'qualification': evidence(qualification_path),
                      'pilotJvms': 9, 'exactQueryExecutions': 27, 'qualifiedExecutions': executions,
                      'runtimeInputsSha256': qualification['runtimeInputsSha256'], 'jdkInputsSha256': qualification['jdkInputsSha256']}))


if __name__ == '__main__':
    main()
